import{z as D,x as s,o as r,c as A,q as l,j as o,D as e,d as t,s as S,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"三阶占优","description":"","frontmatter":{"title":"三阶占优","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/third-order-sd.md","filePath":"econ/third-order-sd.md","lastUpdated":1791063341000}'),B={name:"econ/third-order-sd.md"};function d(p,E,u,m,F,T){const i=s("Mermaid");return r(),A("div",null,[E[2]||(E[2]=l('<h1 id="三阶占优" tabindex="-1">三阶占优 <a class="header-anchor" href="#三阶占优" aria-label="Permalink to &quot;三阶占优&quot;">​</a></h1><div class="epigraph"><p>均值与展形都不足以让所有谨慎的人同意时，还要看质量是堆在左尾还是右尾——那是三阶占优，不是把方差再估一次。</p><footer>—— 据 Whitmore, Third-Degree Stochastic Dominance, American Economic Review, 1970 整理</footer></div><p><a href="/econ/sosd-mps">上一课</a>把等均值的 SOSD 与均值保持展开收成三条等价，并声明方差不是定义。本课不重写 MPS 的噪声表示，也不把积分条件 \\(\\int F\\) 再推一遍。缺口是：许多分布对均值相同、SOSD 不可比——一边更散在左尾，一边偏右。一切凹 \\(u\\) 会分裂；但一切<strong>谨慎</strong>的 \\(u\\)（\\(u&#39;&#39;&#39;\\gt 0\\)）仍可能同意。Whitmore 的三阶占优（TSD）就是这条偏序。谨慎课已经给出 \\(u&#39;&#39;&#39;\\)；本课把它接到分布上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SOSD 要求对一切递增凹 \\(u\\) 都有 \\(\\mathbb{E}u(X)\\ge\\mathbb{E}u(Y)\\)。偏度不同、二阶积分交叉时，这条偏序沉默。缺口不是再指定一条 \\(r_A\\)，而是收窄函数类：递增、凹、且 \\(u&#39;&#39;&#39;\\ge 0\\)。Whitmore 给出积分刻画：记 \\(H_F(z)=\\int_{-\\infty}^z F\\)，\\(K_F(x)=\\int_{-\\infty}^x H_F\\)，则 \\(X\\) 三阶占优 \\(Y\\) 当</p> \\[K_F(x)\\le K_G(x)\\quad\\forall x,\\qquad H_F(\\infty)\\le H_G(\\infty), \\]<p>并通常要求均值 \\(X\\) 不差于 \\(Y\\)。第三项 \\(H_F(\\infty)\\) 与均值有关；等均值时只剩双重积分条件。本课对象仍是一维无名财富，与上一课相同，只是多积一次。</p><h3 id="右偏不是「方差更小」" tabindex="-1">右偏不是「方差更小」 <a class="header-anchor" href="#右偏不是「方差更小」" aria-label="Permalink to &quot;右偏不是「方差更小」&quot;">​</a></h3><p>把质量从中间挪到右尾、同时填左尾的某一类转移，可以保持均值甚至保持 SOSD 不可比，却提高偏度。谨慎者喜欢这种转移，因为 \\(u&#39;\\) 凸：左尾的边际效用被加重，他们更讨厌下行。这与 MPS 正交：MPS 两端对称地展开，一切凹 \\(u\\) 都讨厌；TSD 管的是<strong>不对称</strong>的搬动。不要把「偏度为正」写成 TSD 的定义——定义是积分，偏度只是方向直觉。</p><p><span class="marginnote">「谨慎」（\\(u&#39;&#39;&#39;\\gt 0\\)）翻译成大白话：财富越低，每少一块钱就越疼——边际效用在左尾变陡。直觉实例：工资 5000 元的人丢 1000 元，比工资 50000 元的人丢 1000 元疼得多；谨慎者因此额外讨厌「最坏情形」，这也是预防性储蓄的微观理由。</span></p><p><span class="marginnote">单次交叉的 CDF 往往给出 SOSD；TSD 允许 CDF 与一阶积分都交叉，只要双重积分不交叉。几何上多了一层面积约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较两个已给的 \\(F,G\\)：先查 SOSD；不可比再查双重积分与均值。不必估 \\(u\\)，也不必估 \\(\\pi\\)。类比显示偏好：公理直接打在分布上。若只报偏度系数或三阶矩，既非必要也非充分——与方差不是 SOSD 同一逻辑。</p><p>与 Kimball 的接口：预防性储蓄是「同一人面对展形是否多存」；TSD 是「所有谨慎者是否同意哪份分布更好」。前者是一阶条件，后者是偏序。二次效用 \\(u&#39;&#39;&#39;=0\\)，对 TSD 的严格部分无差别，又一次被排除。</p>',14)),(r(),o(n,null,{default:e(()=>[S(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MPS%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E7%AD%89%E5%9D%87%E5%80%BC%20SOSD%20%3D%20MPS%22%5D%20--%3E%20GAP%5B%22SOSD%20%E4%B8%8D%E5%8F%AF%E6%AF%94%EF%BC%9A%E5%81%8F%E5%BA%A6%22%5D%0A%20%20GAP%20--%3E%20TSD%5B%22TSD%EF%BC%9A%E4%B8%80%E5%88%87%E8%B0%A8%E6%85%8E%20u%20%E5%90%8C%E6%84%8F%22%5D%0A%20%20PRU%5B%22%E5%B7%B2%E6%9C%89%EF%BC%9Au'''%20%3E%200%22%5D%20--%3E%20TSD%0A%20%20TSD%20--%3E%20INT%5B%22%E5%8F%8C%E9%87%8D%E7%A7%AF%E5%88%86%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20TSD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%BB%99%E7%8A%B6%E6%80%81%E8%B5%B7%E5%90%8D%E5%AD%97%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"本课仍比较无名分布。哪一个状态穷、有没有 Arrow 证券，下一课才引入。也不把左尾写成限价簿上的下跌深度。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"双重积分的机制是把 SOSD 的面积再累加：左尾多出来的、未被中间补偿的质量，对 \\(u'''\\gt 0\\) 的人权重更大。Taylor 展开里，\\(u'''\\) 乘三阶矩；但全局等价仍是积分，不是矩。均值相同且 SOSD 成立，则 TSD 自动成立——函数类更窄，偏序更弱（更容易「占优」）。TSD 成立而 SOSD 不成立，才是本课真正补上的缺口。",-1)),E[6]||(E[6]=a("p",null,"与均值方差的重逢更窄：正态被 \\((\\mu,\\sigma)\\) 钉死，没有独立的偏度，TSD 不增加信息。非对称、跳跃、期权式支付，TSD 才开口。上一课说「三阶占优主干用不到」是相对于 MPS 定义；本课把它从边注升级，因为谨慎已经在课序里出现了。",-1)),E[7]||(E[7]=a("p",null,[a("span",{class:"marginnote"},"Whitmore 1970 把 Hadar–Russell 的积分阶梯往上推一层。后续「增加下行风险」（Menezes–Geiss–Tressler）是等均值、等方差下的左尾转移，比 TSD 更窄。本课只钉 Whitmore。")],-1)),E[8]||(E[8]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：两份工作期望收入相同——甲极少变动但一旦出事就是大病返贫；乙偶尔波动、波动多为加薪。风险厌恶者只要求「不更散」，未必排得出名次；谨慎者却一致偏好乙：甲把质量堆在已经很疼的左尾，乙把惊喜堆在不那么疼的右尾。TSD 就是把这群「额外怕左尾的人」的共同排序形式化。")],-1)),(r(),o(n,null,{default:e(()=>[S(i,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20FSD%5B%22FSD%EF%BC%9A%E4%B8%80%E5%88%87%E9%80%92%E5%A2%9E%20u%20%E5%90%8C%E6%84%8F%22%5D%20--%3E%20SOSD%5B%22SOSD%EF%BC%9A%E5%86%8D%E5%8A%A0%E5%87%B9%E6%80%A7%EF%BC%8C%E4%B8%80%E5%88%87%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%E8%80%85%E5%90%8C%E6%84%8F%22%5D%0A%20%20SOSD%20--%3E%20TSD%5B%22TSD%EF%BC%9A%E5%86%8D%E5%8A%A0%E8%B0%A8%E6%85%8E%20u'''%3E0%EF%BC%8C%E8%B0%A8%E6%85%8E%E8%80%85%E5%90%8C%E6%84%8F%22%5D%0A%20%20SOSD%20--%3E%20IMPL%5B%22SOSD%20%E6%88%90%E7%AB%8B%E5%88%99%20TSD%20%E8%87%AA%E5%8A%A8%E6%88%90%E7%AB%8B%22%5D%0A%20%20TSD%20--%3E%20WEAK%5B%22%E5%90%8C%E6%84%8F%E4%BA%BA%E7%BE%A4%E6%94%B6%E7%AA%84%20%E2%86%92%20%E5%81%8F%E5%BA%8F%E6%9B%B4%E5%BC%B1%20%E2%86%92%20%E5%8F%AF%E6%AF%94%E7%9A%84%E5%88%86%E5%B8%83%E6%9B%B4%E5%A4%9A%22%5D%0A%20%20TSD%20--%3E%20CASE%5B%22%E4%B8%BB%E5%9C%BA%EF%BC%9A%E7%AD%89%E5%9D%87%E5%80%BC%E4%B8%94%20SOSD%20%E4%B8%8D%E5%8F%AF%E6%AF%94%22%5D%0A%20%20CASE%20--%3E%20DIR%5B%22%E8%B4%A8%E9%87%8F%E5%A0%86%E5%8F%B3%E5%B0%BE%E8%80%85%E8%83%9C%E8%BF%87%E5%A0%86%E5%B7%A6%E5%B0%BE%E8%80%85%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[9]||(E[9]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>占优仍是偏序：许多分布对 TSD 也不可比，必须回到特定 \\(u\\) 或 \\(\\pi\\)。多维要把积分改成多维；本课只钉一维。独立性失败则效用刻画塌，积分条件只剩几何。模糊没有 \\(F\\)。</p><p>也不要把 TSD 当资产定价因子。偏度偏好可以进入后课的或有要求权，但价格由 \\(q\\) 决定，不是由占优给出。本课没有市场。</p><p>后课默认：SOSD 沉默时，可再问 TSD；同意的人是谨慎者，不是全体风险厌恶者。方差与偏度系数都不能代替积分条件。</p><p><span class="marginnote">常见误区：初学者容易把「偏度为正」当成 TSD 的定义或充分条件。定义是双重积分不等式加均值约束，偏度只是常见的方向直觉；只报三阶矩，既不充分也不必要——与「方差小不代表 SOSD 占优」是同一个错误换个楼层再犯。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TSD：一切递增、凹、谨慎的 \\(u\\) 同意；积分是 CDF 的双重原函数。</li><li>它弱于 SOSD，管的是 SOSD 不可比时的偏度方向。</li><li>三阶矩不是定义；二次效用对严格 TSD 无感觉。</li><li>无名分布到此；下一课把结果绑上有名字的状态。</li><li>出处：Whitmore, <em>AER</em>, 1970；Kimball 的谨慎提供效用类。</li></ul>',7))])}const f=D(B,[["render",d]]);export{C as __pageData,f as default};
